{"command":"mkdir -p src tests && cat > src/document.py <<'PY'
"""A small HTML tree builder and deterministic HTML serializer.

The parser deals with documents rather than XML: omitted document wrappers,
optional end tags, table sections, raw text, and foreign elements are handled
while building the tree. Attribute order is retained for round-trip output.
"""
from html import unescape
import re

VOID = set('area base basefont bgsound br col embed frame hr img input keygen link meta param source track wbr'.split())
RAW = set('script style xmp iframe noembed noframes noscript plaintext'.split())
RCDATA = {'textarea', 'title'}
HEAD = set('base basefont bgsound link meta title noscript noframes style script template'.split())
BLOCK = set('address article aside blockquote center details dialog dir div dl fieldset figcaption figure footer header hgroup hr main menu nav ol p section summary ul'.split())
FORMATTING = set('a b big code em font i nobr s small strike strong tt u'.split())
SPECIAL = BLOCK | set('html body head caption col colgroup dd dt li listing pre table tbody td tfoot th thead tr form h1 h2 h3 h4 h5 h6 button select option optgroup textarea applet marquee object'.split())
WS = ' \t\n\r\f'
SVG_TAGS = {x.lower(): x for x in 'altGlyph altGlyphDef altGlyphItem animateColor animateMotion animateTransform clipPath feBlend feColorMatrix feComponentTransfer feComposite feConvolveMatrix feDiffuseLighting feDisplacementMap feDistantLight feDropShadow feFlood feFuncA feFuncB feFuncG feFuncR feGaussianBlur feImage feMerge feMergeNode feMorphology feOffset fePointLight feSpecularLighting feSpotLight feTile feTurbulence foreignObject glyphRef linearGradient radialGradient textPath'.split()}
SVG_ATTRS = {x.lower(): x for x in 'attributeName attributeType baseFrequency baseProfile calcMode clipPathUnits diffuseConstant edgeMode filterUnits glyphRef gradientTransform gradientUnits kernelMatrix kernelUnitLength keyPoints keySplines keyTimes lengthAdjust limitingConeAngle markerHeight markerUnits markerWidth maskContentUnits maskUnits numOctaves pathLength patternContentUnits patternTransform patternUnits pointsAtX pointsAtY pointsAtZ preserveAlpha preserveAspectRatio primitiveUnits refX refY repeatCount repeatDur requiredExtensions requiredFeatures specularConstant specularExponent spreadMethod startOffset stdDeviation stitchTiles surfaceScale systemLanguage tableValues targetX targetY textLength viewBox viewTarget xChannelSelector yChannelSelector zoomAndPan'.split()}

class Node:
    def __init__(self, tag='', attrs=None, text='', kind='element', ns='html', void=None):
        self.tag = tag
        self.attrs = dict(attrs or ())
        self.text = text
        self.kind = kind
        self.ns = ns
        self.void = (tag in VOID and ns == 'html') if void is None else void
        self.children = []
        self.parent = None

    def append(self, child):
        if child.parent is not None:
            child.parent.children.remove(child)
        child.parent = self
        self.children.append(child)
        return child

    def insert(self, i, child):
        if child.parent is not None:
            child.parent.children.remove(child)
        child.parent = self
        self.children.insert(i, child)
        return child

    def remove(self):
        if self.parent:
            self.parent.children.remove(self)
            self.parent = None

    def walk(self):
        yield self
        for c in self.children:
            yield from c.walk()

    def content(self):
        if self.kind == 'text':
            return self.text
        return ''.join(c.content() for c in self.children if c.kind in ('element', 'text'))

    def add_text(self, text):
        if not text:
            return
        if self.children and self.children[-1].kind == 'text':
            self.children[-1].text += text
        else:
            self.append(Node(kind='text', text=text))


def attr_unescape(s):
    # In an attribute an unterminated named reference followed by '=' or an
    # alphanumeric character is literal, unlike a reference in normal text.
    def decode(m):
        value = m.group(0)
        if value[1:2] != '#' and not value.endswith(';'):
            rest = s[m.end():m.end()+1]
            if rest and (rest.isascii() and rest.isalnum() or rest == '='):
                return value
        return unescape(value)
    return re.sub(r'&(?:#[xX][0-9a-fA-F]+;?|#[0-9]+;?|[a-zA-Z][a-zA-Z0-9]*;?)', decode, s)


def parse_start(raw):
    m = re.match(r'<([a-zA-Z][^\s/>\x00]*)', raw)
    if not m:
        return None
    tag = m.group(1).lower()
    attrs = {}
    pos = m.end()
    while pos < len(raw):
        while pos < len(raw) and raw[pos] in WS + '/>':
            pos += 1
        if pos >= len(raw):
            break
        m = re.match(r'[^\s=/>]+', raw[pos:])
        if not m:
            pos += 1
            continue
        key = m.group(0).lower().replace('\x00', '\ufffd')
        pos += m.end()
        while pos < len(raw) and raw[pos] in WS:
            pos += 1
        value = ''
        if pos < len(raw) and raw[pos] == '=':
            pos += 1
            while pos < len(raw) and raw[pos] in WS:
                pos += 1
            if pos < len(raw) and raw[pos] in "\"'":
                q = raw[pos]
                pos += 1
                end = raw.find(q, pos)
                if end < 0:
                    end = len(raw)
                value = raw[pos:end]
                pos = end + 1
            else:
                m = re.match(r'[^\s>]*', raw[pos:])
                value = m.group(0)
                pos += len(value)
        if key not in attrs:
            attrs[key] = attr_unescape(value.replace('\x00', '\ufffd'))
    return tag, attrs, raw.rstrip().endswith('/>')


class HTMLParser:
    def __init__(self):
        self.root = Node(kind='document')
        self.html = None
        self.head = None
        self.body = None
        self.stack = []
        self.mode = 'initial'
        self.formatting = []
        self.form = None
        self.frameset_ok = True
        self.skip_lf = False

    def current(self):
        return self.stack[-1] if self.stack else self.root

    def ensure_html(self, attrs=None):
        if self.html is None:
            self.html = self.root.append(Node('html', attrs))
            self.stack = [self.html]
        return self.html

    def ensure_head(self, attrs=None):
        self.ensure_html()
        if self.head is None:
            self.head = self.html.append(Node('head', attrs))
        return self.head

    def ensure_body(self, attrs=None):
        self.ensure_head()
        if self.body is None:
            self.body = self.html.append(Node('body', attrs))
        self.stack = [self.html, self.body]
        self.mode = 'body'
        return self.body

    def close_to(self, tag):
        for i in range(len(self.stack)-1, -1, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                return True
        return False

    def has(self, tag):
        return any(n.tag == tag for n in self.stack)

    def in_scope(self, tag):
        for n in reversed(self.stack):
            if n.tag == tag:
                return True
            if n.tag in ('table', 'html', 'template', 'td', 'th', 'marquee', 'object', 'applet'):
                return False
        return False

    def close_p(self):
        if self.in_scope('p'):
            self.close_to('p')

    def implied(self, except_tag=''):
        while self.stack and self.stack[-1].tag in {'dd','dt','li','optgroup','option','p','rb','rp','rt','rtc'} - {except_tag}:
            self.stack.pop()

    def reconstruct(self):
        if not self.formatting:
            return
        start = len(self.formatting)
        while start and self.formatting[start-1] is not None and self.formatting[start-1] not in self.stack:
            start -= 1
        for i in range(start, len(self.formatting)):
            old = self.formatting[i]
            new = Node(old.tag, old.attrs, ns=old.ns)
            self.insert_node(new)
            self.stack.append(new)
            self.formatting[i] = new

    def foster_parent(self):
        for n in reversed(self.stack):
            if n.tag == 'table':
                if n.parent:
                    return n.parent, n.parent.children.index(n)
                break
        return (self.stack[0] if self.stack else self.root), None

    def insert_node(self, node, foster=False):
        if foster:
            parent, idx = self.foster_parent()
            if idx is not None:
                parent.insert(idx, node)
            else:
                parent.append(node)
        else:
            self.current().append(node)
        return node

    def element(self, tag, attrs=None, ns='html', selfclose=False, foster=False):
        node = Node(tag, attrs, ns=ns)
        self.insert_node(node, foster)
        if not node.void and not (selfclose and ns != 'html'):
            self.stack.append(node)
        return node

    def text(self, value, raw=False):
        if self.skip_lf:
            if value.startswith('\n'):
                value = value[1:]
            self.skip_lf = False
        if not value:
            return
        if raw:
            self.current().add_text(value.replace('\x00', '\ufffd'))
            return
        value = value.replace('\x00', '')
        if self.mode in ('initial', 'before_html'):
            value = value.lstrip(WS)
            if not value:
                return
            self.ensure_html()
            self.mode = 'before_head'
        if self.mode == 'before_head':
            value = value.lstrip(WS)
            if not value:
                return
            self.stack = [self.ensure_html(), self.ensure_head()]
            self.mode = 'head'
        if self.mode == 'head':
            if self.current() is self.head:
                m = re.match(r'[\t\n\f\r ]*', value)
                self.head.add_text(m.group(0))
                value = value[m.end():]
                if not value:
                    return
                self.stack = [self.html]
                self.mode = 'after_head'
            else:
                self.current().add_text(value)
                return
        if self.mode == 'after_head':
            m = re.match(r'[\t\n\f\r ]*', value)
            self.html.add_text(m.group(0))
            value = value[m.end():]
            if not value:
                return
            self.ensure_body()
        if self.mode in ('after_body', 'after_html'):
            if not value.strip(WS):
                self.body.add_text(value)
                return
            self.stack = [self.html, self.body]
            self.mode = 'body'
        if self.mode in ('frameset','after_frameset'):
            self.current().add_text(''.join(c for c in value if c in WS))
            return
        if value.strip(WS):
            self.frameset_ok = False
        table_context = self.current().tag in ('table','tbody','thead','tfoot','tr')
        if table_context and value.strip(WS):
            parent, idx = self.foster_parent()
            if idx is not None:
                if idx and parent.children[idx-1].kind == 'text':
                    parent.children[idx-1].text += value
                else:
                    parent.insert(idx, Node(kind='text', text=value))
            else:
                parent.add_text(value)
            return
        self.reconstruct()
        self.current().add_text(value)

    def comment(self, value):
        node = Node(kind='comment', text=value)
        if self.mode in ('initial','before_html','after_html'):
            self.root.append(node)
        elif self.mode == 'after_body':
            self.html.append(node)
        else:
            self.current().append(node)

    def doctype(self, value):
        if self.mode == 'initial':
            name = re.match(r'\s*doctype\s+([^\s>]+)', value, re.I)
            self.root.append(Node(kind='doctype', text=name.group(1).lower() if name else ''))
            self.mode = 'before_html'

    def start(self, tag, attrs, selfclose=False):
        self.skip_lf = False
        if self.mode in ('initial','before_html'):
            self.ensure_html(attrs if tag == 'html' else None)
            self.mode = 'before_head'
            if tag == 'html':
                return
        if tag == 'html':
            for k,v in attrs.items():
                self.html.attrs.setdefault(k,v)
            return
        if self.mode == 'before_head':
            self.ensure_head(attrs if tag == 'head' else None)
            self.stack = [self.html,self.head]
            self.mode = 'head'
            if tag == 'head':
                return
        if self.mode == 'head':
            if tag in HEAD:
                self.element(tag, attrs)
                return
            if tag == 'head':
                return
            self.stack = [self.html]
            self.mode = 'after_head'
        if self.mode == 'after_head':
            if tag == 'body':
                self.ensure_body(attrs)
                self.frameset_ok = False
                return
            if tag == 'frameset':
                self.stack = [self.html]
                self.body = self.element(tag,attrs)
                self.mode = 'frameset'
                return
            if tag in HEAD:
                self.stack = [self.html, self.head]
                self.element(tag, attrs)
                if self.current() is self.head:
                    self.stack = [self.html]
                return
            if tag == 'head':
                return
            self.ensure_body()
        if self.mode in ('after_body','after_html'):
            self.stack = [self.html,self.body]
            self.mode = 'body'
        if self.mode in ('frameset','after_frameset'):
            if tag in ('frameset','frame','noframes'):
                self.element(tag, attrs)
            return
        # Foreign content has XML-like names and self-closing elements.
        cur = self.current()
        foreign = cur.ns != 'html' and cur.tag not in ('foreignObject','desc','title')
        if cur.ns == 'math' and cur.tag in ('mi','mo','mn','ms','mtext') and tag not in ('mglyph','malignmark'):
            foreign = False
        if foreign:
            breakout = tag in {'b','big','blockquote','body','br','center','code','dd','div','dl','dt','em','embed','h1','h2','h3','h4','h5','h6','head','hr','i','img','li','listing','menu','meta','nobr','ol','p','pre','ruby','s','small','span','strong','strike','sub','sup','table','tt','u','ul','var'} or tag == 'font' and any(k in attrs for k in ('color','face','size'))
            if breakout:
                while self.current().ns != 'html' and self.current().tag not in ('foreignObject','desc','title'):
                    self.stack.pop()
            else:
                ns = cur.ns
                if ns == 'svg':
                    tag = SVG_TAGS.get(tag, tag)
                    attrs = {SVG_ATTRS.get(k,k):v for k,v in attrs.items()}
                elif ns == 'math' and 'definitionurl' in attrs:
                    attrs['definitionURL'] = attrs.pop('definitionurl')
                self.element(tag, attrs, ns, selfclose)
                return
        if self.has('select'):
            if tag == 'option':
                if self.current().tag == 'option': self.stack.pop()
                self.element(tag,attrs)
            elif tag == 'optgroup':
                if self.current().tag == 'option': self.stack.pop()
                if self.current().tag == 'optgroup': self.stack.pop()
                self.element(tag,attrs)
            elif tag == 'select':
                self.close_to('select')
            elif tag in ('input','keygen','textarea'):
                self.close_to('select')
                self.start(tag,attrs,selfclose)
            elif tag in ('script','template'):
                self.element(tag,attrs)
            return
        if tag == 'body':
            if self.body:
                for k,v in attrs.items(): self.body.attrs.setdefault(k,v)
            self.frameset_ok = False
            return
        if tag == 'head':
            return
        if tag == 'frameset':
            if self.frameset_ok and self.body:
                self.body.remove()
                self.stack = [self.html]
                self.body = self.element(tag,attrs)
                self.mode = 'frameset'
            return
        if tag in ('frame',):
            return
        if tag == 'image':
            tag = 'img'
        if tag in ('caption','colgroup','tbody','thead','tfoot','tr','td','th','col'):
            if not self.has('table'):
                return
            if tag in ('caption','colgroup','tbody','thead','tfoot'):
                while self.current().tag not in ('table','html','template'):
                    self.stack.pop()
                self.element(tag,attrs)
                return
            if tag == 'col':
                if self.current().tag != 'colgroup':
                    while self.current().tag not in ('table','html','template'):
                        self.stack.pop()
                    self.element('colgroup')
                self.element(tag,attrs)
                return
            if tag == 'tr':
                while self.current().tag not in ('table','tbody','thead','tfoot','html','template'):
                    self.stack.pop()
                if self.current().tag == 'table':
                    self.element('tbody')
                self.element(tag,attrs)
                return
            if tag in ('td','th'):
                while self.current().tag not in ('tr','tbody','thead','tfoot','table','html','template'):
                    self.stack.pop()
                if self.current().tag == 'table': self.element('tbody')
                if self.current().tag in ('tbody','thead','tfoot'): self.element('tr')
                self.element(tag,attrs)
                self.formatting.append(None)
                return
        if self.current().tag == 'colgroup' and tag not in ('template',):
            self.stack.pop()
        foster = self.current().tag in ('table','thead','tbody','tfoot','tr') and tag not in ('style','script','template','input','form','table')
        if tag in BLOCK or tag in ('pre','listing','h1','h2','h3','h4','h5','h6'):
            self.close_p()
            if tag in ('h1','h2','h3','h4','h5','h6') and self.current().tag in ('h1','h2','h3','h4','h5','h6'):
                self.stack.pop()
            self.element(tag,attrs,foster=foster)
            if tag in ('pre','listing'):
                self.skip_lf = True
                self.frameset_ok = False
            if tag == 'hr':
                self.frameset_ok = False
            return
        if tag == 'form':
            if self.form is not None and not self.has('template'): return
            self.close_p()
            node = self.element(tag,attrs)
            self.form = node
            if self.has('table') and self.current().tag not in ('td','th') and len(self.stack)>1 and self.stack[-2].tag in ('table','tbody','tr'):
                self.stack.pop()
            return
        if tag in ('li','dd','dt'):
            for n in reversed(self.stack):
                if n.tag == tag or tag in ('dd','dt') and n.tag in ('dd','dt'):
                    self.close_to(n.tag)
                    break
                if n.tag in SPECIAL and n.tag not in ('address','div','p'):
                    break
            self.close_p()
            self.element(tag,attrs,foster=foster)
            self.frameset_ok = False
            return
        if tag == 'plaintext':
            self.close_p()
            self.element(tag,attrs)
            return
        if tag == 'button' and self.in_scope('button'):
            self.implied()
            self.close_to('button')
        if tag in FORMATTING:
            if tag in ('a','nobr'):
                old = next((n for n in reversed(self.formatting) if n and n.tag == tag),None)
                if old:
                    self.end(tag)
                    if old in self.formatting: self.formatting.remove(old)
                    if old in self.stack: self.stack.remove(old)
            self.reconstruct()
            node = self.element(tag,attrs,foster=foster)
            self.formatting.append(node)
            return
        if tag == 'table':
            if self.has('table') and not any(n.tag in ('td','th') for n in self.stack[self.stack.index(next(n for n in self.stack if n.tag=='table'))+1:]):
                self.close_to('table')
            self.close_p()
            self.element(tag,attrs)
            self.frameset_ok = False
            return
        if tag in ('option','optgroup') and self.current().tag == 'option':
            self.stack.pop()
        if tag in ('rt','rp'):
            self.implied()
        if tag in ('svg','math'):
            self.reconstruct()
            if tag == 'svg': attrs = {SVG_ATTRS.get(k,k):v for k,v in attrs.items()}
            self.element(tag,attrs,tag,selfclose,foster)
            return
        if tag == 'xmp': self.close_p()
        if tag not in ('script','style','meta','link','base','title','noframes','noembed','noscript','template'):
            self.reconstruct()
        self.element(tag,attrs,foster=foster)
        if tag in ('applet','marquee','object','template'):
            self.formatting.append(None)
        if tag in ('textarea','pre','listing'):
            self.skip_lf = True
        if tag in ('textarea','select','iframe','xmp','button','img','embed','input') and not (tag == 'input' and attrs.get('type','').lower() == 'hidden'):
            self.frameset_ok = False

    def end(self, tag):
        self.skip_lf = False
        if self.current().ns != 'html':
            for i in range(len(self.stack)-1,-1,-1):
                n = self.stack[i]
                if n.tag.lower() == tag:
                    del self.stack[i:]
                    return
                if n.ns == 'html': break
        if self.mode in ('initial','before_html','before_head'):
            if tag in ('head','body','html','br'):
                self.ensure_html()
                self.ensure_head()
                self.stack = [self.html,self.head]
                self.mode = 'head'
            else:
                return
        if self.mode == 'head':
            if tag == 'head':
                self.stack = [self.html]
                self.mode = 'after_head'
                return
            if tag in ('body','html','br'):
                self.stack = [self.html]
                self.mode = 'after_head'
            else:
                self.close_to(tag)
                return
        if self.mode == 'after_head':
            if self.has(tag) and tag in HEAD:
                self.close_to(tag)
                if self.current() == self.head: self.stack = [self.html]
                return
            if tag in ('body','html','br'):
                self.ensure_body()
            else: return
        if self.mode == 'frameset':
            if tag == 'frameset':
                self.close_to(tag)
                if not self.has('frameset'): self.mode = 'after_frameset'
            elif tag == 'noframes': self.close_to(tag)
            return
        if self.mode == 'after_frameset':
            if tag == 'html': self.mode = 'after_html'
            return
        if self.mode in ('after_body','after_html'):
            if tag == 'html':
                self.mode = 'after_html'
                return
            if tag != 'body':
                self.mode = 'body'
                self.stack = [self.html,self.body]
        if tag == 'body':
            if self.body:
                self.mode = 'after_body'
            return
        if tag == 'html':
            if self.body:
                self.mode = 'after_html'
            return
        if self.has('select') and tag not in ('select','option','optgroup','script','template'):
            return
        if tag == 'br':
            self.start('br',{})
            return
        if tag == 'p':
            if not self.in_scope('p'):
                self.start('p',{})
            self.close_to('p')
            return
        if tag == 'form':
            if self.form:
                if self.form in self.stack: self.stack.remove(self.form)
                self.form = None
            return
        if tag in FORMATTING:
            found = None
            for n in reversed(self.formatting):
                if n is None: break
                if n.tag == tag:
                    found = n
                    break
            if found is None:
                self.close_to(tag)
                return
            if found not in self.stack:
                self.formatting.remove(found)
                return
            idx = self.stack.index(found)
            block = next((n for n in self.stack[idx+1:] if n.tag in SPECIAL),None)
            if block is None:
                del self.stack[idx:]
                self.formatting.remove(found)
                return
            # Reparent a formatting element crossing a block boundary.
            parent = found.parent
            if parent:
                pos = parent.children.index(found)+1
                parent.insert(pos,block)
                clone = Node(found.tag,found.attrs)
                for child in list(block.children): clone.append(child)
                block.append(clone)
                self.formatting.remove(found)
                self.stack.remove(found)
                if clone not in self.stack:
                    self.stack.insert(self.stack.index(block)+1,clone)
                # Adoption finishes with the new formatting element closed.
                self.stack.remove(clone)
            return
        if tag in ('td','th','applet','marquee','object','template'):
            if not self.has(tag): return
            self.close_to(tag)
            while self.formatting:
                if self.formatting.pop() is None: break
            return
        if tag in ('h1','h2','h3','h4','h5','h6'):
            for n in reversed(self.stack):
                if n.tag in ('h1','h2','h3','h4','h5','h6'):
                    self.close_to(n.tag)
                    return
            return
        self.close_to(tag)

    def parse(self, source):
        source = source.replace('\r\n','\n').replace('\r','\n')
        i = 0
        n = len(source)
        while i < n:
            cur = self.current()
            if cur.kind == 'element' and cur.ns == 'html' and cur.tag in RAW | RCDATA:
                tag = cur.tag
                if tag == 'plaintext':
                    self.text(source[i:],raw=True)
                    i = n
                    break
                m = re.search(r'</'+tag+r'(?=[\s/>])[^>]*>',source[i:],re.I)
                end = i+m.start() if m else n
                value = source[i:end]
                if tag in RCDATA:
                    value = unescape(value)
                self.text(value,raw=True)
                if m:
                    self.end(tag)
                    i += m.end()
                else:
                    i = n
                continue
            if source.startswith('<!--',i):
                m = re.search(r'--!?>',source[i+4:])
                end = i+4+m.start() if m else n
                value = source[i+4:end]
                if value == '>': value = ''
                self.comment(value)
                i = i+4+m.end() if m else n
                continue
            if source[i:i+9].lower() == '<!doctype':
                end = source.find('>',i+2)
                if end<0: end=n
                self.doctype(source[i+2:end])
                i=end+1
                continue
            if source.startswith('<![CDATA[',i) and self.current().ns != 'html':
                end = source.find(']]>',i+9)
                if end<0: end=n
                self.text(source[i+9:end],raw=True)
                i=end+3
                continue
            if source.startswith('<!',i) or source.startswith('<?',i):
                end=source.find('>',i+2)
                if end<0: end=n
                self.comment(source[i+2:end] if source[i+1]=='!' else source[i+1:end])
                i=end+1
                continue
            if source.startswith('</',i):
                m=re.match(r'</([a-zA-Z][^\s/>]*)[^>]*>',source[i:])
                if m:
                    self.end(m.group(1).lower())
                    i += m.end()
                    continue
                end=source.find('>',i+2)
                if end>=0:
                    if source[i+2:end]: self.comment(source[i+2:end])
                    i=end+1
                    continue
            if source[i]=='<' and i+1<n and source[i+1].isascii() and source[i+1].isalpha():
                end=i+1
                quote=None
                while end<n:
                    ch=source[end]
                    if quote:
                        if ch==quote: quote=None
                    elif ch in "\"'": quote=ch
                    elif ch=='>': break
                    end+=1
                if end<n:
                    parsed=parse_start(source[i:end+1])
                    if parsed:
                        self.start(*parsed)
                    i=end+1
                    continue
                break
            end=source.find('<',i+1)
            if end<0: end=n
            self.text(unescape(source[i:end]))
            i=end
        self.ensure_html()
        self.ensure_head()
        if self.body is None:
            self.ensure_body()
        return self.root


def parse(source):
    return HTMLParser().parse(source)


def escape_text(s):
    return s.replace('&','&amp;').replace('\u00a0','&nbsp;').replace('<','&lt;').replace('>','&gt;')


def escape_attr(s):
    return s.replace('&','&amp;').replace('\u00a0','&nbsp;').replace('"','&quot;')


def serialize(node, parent=None):
    if node.kind=='text':
        if parent and parent.ns=='html' and parent.tag in RAW:
            return node.text
        return escape_text(node.text)
    if node.kind=='comment': return '<!--'+node.text+'-->'
    if node.kind=='doctype': return '<!DOCTYPE '+node.text+'>'
    if node.kind=='raw': return node.text
    if node.kind=='document': return ''.join(serialize(c,node) for c in node.children)
    out='<'+node.tag+''.join(' '+k+'="'+escape_attr(v)+'"' for k,v in node.attrs.items())+'>'
    if node.void: return out
    return out+''.join(serialize(c,node) for c in node.children)+'</'+node.tag+'>'
