"""A small HTML tree builder and deterministic HTML serializer.

The parser deals with documents rather than XML: omitted document wrappers,
optional end tags, table sections, raw text, and foreign elements are handled
while building the tree. Attribute order is retained for round-trip output.
"""
from html import unescape
import re

VOID = set('area base basefont bgsound br col embed frame hr img input keygen link meta param source track wbr'.split())
RAW = set('script style xmp iframe noembed noframes noscript plaintext'.split())
RCDATA = {'textarea', 'title'}
HEAD = set('base basefont bgsound link meta title noscript noframes style script template'.split())
BLOCK = set('address article aside blockquote center details dialog dir div dl fieldset figcaption figure footer header hgroup hr main menu nav ol p section summary ul'.split())
FORMATTING = set('a b big code em font i nobr s small strike strong tt u'.split())
SPECIAL = BLOCK | set('html body head caption col colgroup dd dt li listing pre table tbody td tfoot th thead tr form h1 h2 h3 h4 h5 h6 button select option optgroup textarea applet marquee object'.split())
WS = ' \t\n\r\f'
SVG_TAGS = {x.lower(): x for x in 'altGlyph altGlyphDef altGlyphItem animateColor animateMotion animateTransform clipPath feBlend feColorMatrix feComponentTransfer feComposite feConvolveMatrix feDiffuseLighting feDisplacementMap feDistantLight feDropShadow feFlood feFuncA feFuncB feFuncG feFuncR feGaussianBlur feImage feMerge feMergeNode feMorphology feOffset fePointLight feSpecularLighting feSpotLight feTile feTurbulence foreignObject glyphRef linearGradient radialGradient textPath'.split()}
SVG_ATTRS = {x.lower(): x for x in 'attributeName attributeType baseFrequency baseProfile calcMode clipPathUnits diffuseConstant edgeMode filterUnits glyphRef gradientTransform gradientUnits kernelMatrix kernelUnitLength keyPoints keySplines keyTimes lengthAdjust limitingConeAngle markerHeight markerUnits markerWidth maskContentUnits maskUnits numOctaves pathLength patternContentUnits patternTransform patternUnits pointsAtX pointsAtY pointsAtZ preserveAlpha preserveAspectRatio primitiveUnits refX refY repeatCount repeatDur requiredExtensions requiredFeatures specularConstant specularExponent spreadMethod startOffset stdDeviation stitchTiles surfaceScale systemLanguage tableValues targetX targetY textLength viewBox viewTarget xChannelSelector yChannelSelector zoomAndPan'.split()}

class Node:
    def __init__(self, tag='', attrs=None, text='', kind='element', ns='html', void=None):
        self.tag = tag
        self.attrs = dict(attrs or ())
        self.text = text
        self.kind = kind
        self.ns = ns
        self.void = (tag in VOID and ns == 'html') if void is None else void
        self.children = []
        self.parent = None

    def append(self, child):
        if child.parent is not None:
            child.parent.children.remove(child)
        child.parent = self
        self.children.append(child)
        return child

    def insert(self, i, child):
        if child.parent is not None:
            child.parent.children.remove(child)
        child.parent = self
        self.children.insert(i, child)
        return child

    def remove(self):
        if self.parent:
            self.parent.children.remove(self)
            self.parent = None

    def walk(self):
        yield self
        for c in self.children:
            yield from c.walk()

    def content(self):
        if self.kind == 'text':
            return self.text
        return ''.join(c.content() for c in self.children if c.kind in ('element', 'text'))

    def add_text(self, text):
        if not text:
            return
        if self.children and self.children[-1].kind == 'text':
            self.children[-1].text += text
        else:
            self.append(Node(kind='text', text=text))


def attr_unescape(s):
    # In an attribute an unterminated named reference followed by '=' or an
    # alphanumeric character is literal, unlike a reference in normal text.
    def decode(m):
        value = m.group(0)
        if value[1:2] != '#' and not value.endswith(';'):
            rest = s[m.end():m.end()+1]
            if rest and (rest.isascii() and rest.isalnum() or rest == '='):
                return value
        return unescape(value)
    return re.sub(r'&(?:#[xX][0-9a-fA-F]+;?|#[0-9]+;?|[a-zA-Z][a-zA-Z0-9]*;?)', decode, s)


def parse_start(raw):
    m = re.match(r'<([a-zA-Z][^\s/>\x00]*)', raw)
    if not m:
        return None
    tag = m.group(1).lower()
    attrs = {}
    pos = m.end()
    while pos < len(raw):
        while pos < len(raw) and raw[pos] in WS + '/>':
            pos += 1
        if pos >= len(raw):
            break
        m = re.match(r'[^\s=/>]+', raw[pos:])
        if not m:
            pos += 1
            continue
        key = m.group(0).lower().replace('\x00', '\ufffd')
        pos += m.end()
        while pos < len(raw) and raw[pos] in WS:
            pos += 1
        value = ''
        if pos < len(raw) and raw[pos] == '=':
            pos += 1
            while pos < len(raw) and raw[pos] in WS:
                pos += 1
            if pos < len(raw) and raw[pos] in "\"'":
                q = raw[pos]
                pos += 1
                end = raw.find(q, pos)
                if end < 0:
                    end = len(raw)
                value = raw[pos:end]
                pos = end + 1
            else:
                m = re.match(r'[^\s>]*', raw[pos:])
                value = m.group(0)
                pos += len(value)
        if key not in attrs:
            attrs[key] = attr_unescape(value.replace('\x00', '\ufffd'))
    return tag, attrs, raw.rstrip().endswith('/>')


class HTMLParser:
    def __init__(self):
        self.root = Node(kind='document')
        self.html = None
        self.head = None
        self.body = None
        self.stack = []
        self.mode = 'initial'
        self.formatting = []
        self.form = None
        self.frameset_ok = True
        self.skip_lf = False

    def current(self):
        return self.stack[-1] if self.stack else self.root

    def ensure_html(self, attrs=None):
        if self.html is None:
            self.html = self.root.append(Node('html', attrs))
            self.stack = [self.html]
        return self.html

    def ensure_head(self, attrs=None):
        self.ensure_html()
        if self.head is None:
            self.head = self.html.append(Node('head', attrs))
        return self.head

    def ensure_body(self, attrs=None):
        self.ensure_head()
        if self.body is None:
            self.body = self.html.append(Node('body', attrs))
        self.stack = [self.html, self.body]
        self.mode = 'body'
        return self.body

    def close_to(self, tag):
        for i in range(len(self.stack)-1, -1, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                return True
        return False

    def has(self, tag):
        return any(n.tag == tag for n in self.stack)

    def in_scope(self, tag):
        for n in reversed(self.stack):
            if n.tag == tag:
                return True
            if n.tag in ('table', 'html', 'template', 'td', 'th', 'marquee', 'object', 'applet'):
                return False
        return False

    def close_p(self):
        if self.in_scope('p'):
            self.close_to('p')

    def implied(self, except_tag=''):
        while self.stack and self.stack[-1].tag in {'dd','dt','li','optgroup','option','p','rb','rp','rt','rtc'} - {except_tag}:
            self.stack.pop()

    def reconstruct(self):
        if not self.formatting:
            return
        start = len(self.formatting)
        while start and self.formatting[start-1] is not None and self.formatting[start-1] not in self.stack:
            start -= 1
        for i in range(start, len(self.formatting)):
            old = self.formatting[i]
            new = Node(old.tag, old.attrs, ns=old.ns)
            self.insert_node(new)
            self.stack.append(new)
            self.formatting[i] = new

    def foster_parent(self):
        for n in reversed(self.stack):
            if n.tag == 'table':
                if n.parent:
                    return n.parent, n.parent.children.index(n)
                break
        return (self.stack[0] if self.stack else self.root), None

    def insert_node(self, node, foster=False):
        if foster:
            parent, idx = self.foster_parent()
            if idx is not None:
                parent.insert(idx, node)
            else:
                parent.append(node)
        else:
            self.current().append(node)
        return node

    def element(self, tag, attrs=None, ns='html', selfclose=False, foster=False):
        node = Node(tag, attrs, ns=ns)
        self.insert_node(node, foster)
        if not node.void and not (selfclose and ns != 'html'):
            self.stack.append(node)
        return node

    def text(self, value, raw=False):
        if self.skip_lf:
            if value.startswith('\n'):
                value = value[1:]
            self.skip_lf = False
        if not value:
            return
        if raw:
            self.current().add_text(value.replace('\x00', '\ufffd'))
            return
        value = value.replace('\x00', '')
        if self.mode in ('initial', 'before_html'):
            value = value.lstrip(WS)
            if not value:
                return
            self.ensure_html()
            self.mode = 'before_head'
        if self.mode == 'before_head':
            value = value.lstrip(WS)
            if not value:
                return
            self.stack = [self.ensure_html(), self.ensure_head()]
            self.mode = 'head'
        if self.mode == 'head':
            if self.current() is self.head:
                m = re.match(r'[\t\n\f\r ]*', value)
                self.head.add_text(m.group(0))
                value = value[m.end():]
                if not value:
                    return
                self.stack = [self.html]
                self.mode = 'after_head'
            else:
                self.current().add_text(value)
                return
        if self.mode == 'after_head':
            m = re.match(r'[\t\n\f\r ]*', value)
            self.html.add_text(m.group(0))
            value = value[m.end():]
            if not value:
                return
            self.ensure_body()
        if self.mode in ('after_body', 'after_html'):
            if not value.strip(WS):
                self.body.add_text(value)
                return
            self.stack = [self.html, self.body]
            self.mode = 'body'
        if self.mode in ('frameset','after_frameset'):
            self.current().add_text(''.join(c for c in value if c in WS))
            return
        if value.strip(WS):
            self.frameset_ok = False
        table_context = self.current().tag in ('table','tbody','thead','tfoot','tr')
        if table_context and value.strip(WS):
            parent, idx = self.foster_parent()
            if idx is not None:
                if idx and parent.children[idx-1].kind == 'text':
                    parent.children[idx-1].text += value
                else:
                    parent.insert(idx, Node(kind='text', text=value))
            else:
                parent.add_text(value)
            return
        self.reconstruct()
        self.current().add_text(value)

    def comment(self, value):
        node = Node(kind='comment', text=value)
        if self.mode in ('initial','before_html','after_html'):
            self.root.append(node)
        elif self.mode == 'after_body':
            self.html.append(node)
        else:
            self.current().append(node)

    def doctype(self, value):
        if self.mode == 'initial':
            name = re.match(r'\s*doctype\s+([^\s>]+)', value, re.I)
            self.root.append(Node(kind='doctype', text=name.group(1).lower() if name else ''))
            self.mode = 'before_html'

    def start(self, tag, attrs, selfclose=False):
