def parse(source):
    return HTMLParser().parse(source)


def escape_text(s):
    return s.replace('&','&amp;').replace('\u00a0','&nbsp;').replace('<','&lt;').replace('>','&gt;')


def escape_attr(s):
    return s.replace('&','&amp;').replace('\u00a0','&nbsp;').replace('"','&quot;')


def serialize(node, parent=None):
    if node.kind=='text':
        if parent and parent.ns=='html' and parent.tag in RAW:
            return node.text
        return escape_text(node.text)
    if node.kind=='comment': return '<!--'+node.text+'-->'
    if node.kind=='doctype': return '<!DOCTYPE '+node.text+'>'
    if node.kind=='raw': return node.text
    if node.kind=='document': return ''.join(serialize(c,node) for c in node.children)
    out='<'+node.tag+''.join(' '+k+'="'+escape_attr(v)+'"' for k,v in node.attrs.items())+'>'
    if node.void: return out
    return out+''.join(serialize(c,node) for c in node.children)+'</'+node.tag+'>'
