def encoding(label):
    if not label: return None
    label=label.strip().lower()
    label=ENCODING_ALIASES.get(label,label)
    if label=='x-user-defined': return label
    try:
        name=codecs.lookup(label).name
        if name in ('utf-7','utf-32','utf-32-le','utf-32-be','unicode-escape','raw-unicode-escape','base64','hex','rot-13','unicode-internal'):
            return None
        return name
    except LookupError:
        return None


def decode_bytes(data,enc='utf-8'):
    if data.startswith(b'\xef\xbb\xbf'): return data[3:].decode('utf-8','replace')
    if data.startswith(b'\xff\xfe'): return data[2:].decode('utf-16le','replace')
    if data.startswith(b'\xfe\xff'): return data[2:].decode('utf-16be','replace')
    if enc=='x-user-defined':
        return ''.join(chr(x if x<128 else 0xf700+x) for x in data)
    if enc in ('cp1252','cp1250','cp1251','cp1253','cp1254','cp1255','cp1256','cp1257','cp1258'):
        # WHATWG single-byte decoders preserve the undefined control values.
        out=[]
        for b in data:
            try: out.append(bytes([b]).decode(enc))
            except UnicodeDecodeError: out.append(chr(b))
        return ''.join(out)
    try: return data.decode(enc or 'utf-8','replace')
    except (LookupError,ValueError): return data.decode('utf-8','replace')


def encode_text(text,enc):
    if enc in ('utf-16le','utf-16be','utf-16-le','utf-16-be',None): enc='utf-8'
    if enc=='x-user-defined':
        out=bytearray()
        for c in text:
            o=ord(c)
            if o<128: out.append(o)
            elif 0xf780<=o<=0xf7ff: out.append(o-0xf700)
            else: out.extend(('&#'+str(o)+';').encode())
        return bytes(out)
    return text.encode(enc,'xmlcharrefreplace')


def sniff_encoding(data,content_type='',html=False):
    if data.startswith(b'\xef\xbb\xbf'): return 'utf-8'
    if data.startswith(b'\xff\xfe'): return 'utf-16le'
    if data.startswith(b'\xfe\xff'): return 'utf-16be'
    m=re.search(r'charset\s*=\s*["\']?([^\s;"\']+)',content_type,re.I)
    if m and encoding(m.group(1)): return encoding(m.group(1))
    if html:
        from document import parse_start
        sample=data[:1024].decode('latin1')
        sample=re.sub(r'<!--.*?(?:-->|$)','',sample,flags=re.S)
        for match in re.finditer(r'<meta\b[^>]*>',sample,re.I):
            p=parse_start(match.group(0))
            if not p: continue
            a=p[1]
            label=a.get('charset')
            if not label and a.get('http-equiv','').lower()=='content-type':
                mat=re.search(r'charset\s*=\s*["\']?([^\s;"\']+)',a.get('content',''),re.I)
                if mat: label=mat.group(1)
            en=encoding(label)
            if en:
                if en in ('utf-16le','utf-16be','utf-16-le','utf-16-be'): return 'utf-8'
                if en=='x-user-defined': return 'cp1252'
                return en
    return 'utf-8'


def normalize_url(value):
    value=value.strip(''.join(chr(i) for i in range(33)))
    value=value.replace('\t','').replace('\n','').replace('\r','')
    m=re.match(r'^([a-zA-Z][a-zA-Z0-9+.-]*):',value)
    if not m: return None
    scheme=m.group(1).lower()
    if scheme in ('http','https','ftp','file'):
        value=scheme+value[m.end()-1:]
        value=value.replace('\\','/')
        if scheme in ('http','https','ftp'):
            rest=value[len(scheme)+1:].lstrip('/')
            value=scheme+'://'+rest
        try:
            p=url.urlsplit(value)
            if scheme!='file' and not p.hostname: return None
            host=p.hostname or ''
            if ':' in host and not host.startswith('['): host='['+host+']'
            elif host:
                host=host.encode('idna').decode().lower()
            port=p.port
            if port is not None and not ((scheme=='http' and port==80) or (scheme=='https' and port==443) or (scheme=='ftp' and port==21)):
                host+=':'+str(port)
            user=''
            if p.username is not None:
                user=url.quote(p.username,safe='%!$&\'()*+,-._~')
                if p.password is not None: user+=':'+url.quote(p.password,safe='%!$&\'()*+,-._~')
                user+='@'
            if scheme=='file' and host=='localhost': host=''
            path=p.path or '/'
            # Normalize dot segments without dropping an ordinary double slash.
            segments=[]
            for part in path.split('/'):
                decoded=url.unquote(part).lower()
                if decoded=='.':
                    if part==path.split('/')[-1]: pass
                    continue
                if decoded=='..':
                    if len(segments)>1: segments.pop()
                    continue
                segments.append(part)
            clean='/'.join(segments)
            if not clean.startswith('/'): clean='/'+clean
            if path.endswith(('/.','/..','/%2e','/%2E')) and not clean.endswith('/'): clean+='/'
            path=url.quote(clean,safe="/%:@!$&'()*+,-.;=_~[]")
            query=url.quote(p.query,safe="%/?:@!$&()*+,-.;=_~[]\\|^")
            frag=url.quote(p.fragment,safe="%/?:@!$&'()*+,-.;=_~[]\\|^#")
            result=url.urlunsplit((scheme,user+host,path,query,frag))
            # urlunsplit removes empty query/fragment delimiters.
            if value.endswith('#') and not result.endswith('#'): result+='#'
            return result
        except (ValueError,UnicodeError): return None
    rest=value[m.end():]
    return scheme+':'+url.quote(rest,safe="%/?:@!$&'()*+,-.;=_~[]\\|^#\"<>{} ")


def resolve(base,value):
    absolute=normalize_url(value)
    if absolute is not None:
        return absolute
    if base is None:
        return 'data:,'
    b=normalize_url(base)
    if b is None:
        return 'data:,'
    p=url.urlsplit(b)
    if p.scheme not in ('http','https','ftp','file'):
        if value.startswith('#'):
            return b.split('#',1)[0]+value
        return 'data:,'
    val=value.strip().replace('\\','/').replace('\n','').replace('\r','').replace('\t','')
    try: return normalize_url(url.urljoin(b,val)) or 'data:,'
    except ValueError: return 'data:,'


def file_url(path):
    return pathlib.Path(os.path.abspath(path)).as_uri()

MIME_OVERRIDES={'.js':'text/javascript','.mjs':'text/javascript','.ico':'image/x-icon','.woff':'font/woff','.woff2':'font/woff2','.ttf':'font/ttf','.otf':'font/otf','.wav':'audio/wav','.mp3':'audio/mpeg','.ogg':'audio/ogg','.json':'application/json','.vtt':'text/vtt','.svg':'image/svg+xml','.xhtml':'application/xhtml+xml','.htm':'text/html','.html':'text/html'}

def mime_for_path(path):
    ext=posixpath.splitext(path)[1].lower()
    return MIME_OVERRIDES.get(ext) or mimetypes.guess_type(path)[0] or 'application/octet-stream'


def data_url(mime,data):
    return 'data:'+(mime or 'text/plain')+';base64,'+base64.b64encode(data).decode('ascii')


def integrity_ok(value,data):
    if not value: return True
    found=[]
    for item in value.split():
        typ,sep,digest=item.partition('-')
        if sep and typ in ('sha256','sha384','sha512'):
            found.append((int(typ[3:]),base64.b64encode(hashlib.new(typ,data).digest()).decode()==digest.split('?')[0]))
    if not found: return False
    best=max(n for n,b in found)
    return any(b for n,b in found if n==best)

@dataclass
class Resource:
    data: bytes
    mime: str
    url: str
    content_type: str = ''
    successful: bool = True
    error: str = ''

class Redirects(urllib.request.HTTPRedirectHandler):
    def redirect_request(self,req,fp,code,msg,headers,newurl):
        result=super().redirect_request(req,fp,code,msg,headers,newurl)
        if result is not None:
            old=url.urlsplit(req.full_url)
            new=url.urlsplit(newurl)
            if not (old.scheme=='https' and new.scheme=='http'):
                result.add_header('Referer',url.urlunsplit((old.scheme,old.netloc,old.path,old.query,'')))
        return result

class Resources:
    def __init__(self,opts):
        self.opts=opts
        self.cache={}
        self.active=set()
        context=ssl._create_unverified_context() if opts.insecure else ssl.create_default_context()
        handlers=[Redirects(),urllib.request.HTTPSHandler(context=context)]
        self.cookies=None
        if opts.cookie_file:
            self.cookies=self.read_cookies(opts.cookie_file)
            handlers.append(urllib.request.HTTPCookieProcessor(self.cookies))
        self.opener=urllib.request.build_opener(*handlers)

    def log(self,text):
        if not self.opts.quiet:
            sys.stderr.write(text+'\n')

    def read_cookies(self,path):
        import json
        try:
            content=pathlib.Path(path).read_text()
        except (OSError,UnicodeError):
            sys.stderr.write('could not read specified cookie file "'+path+'"\n'); raise SystemExit(1)
        jar=http.cookiejar.CookieJar()
        # Netscape cookie files are the interoperable format accepted here.
        try:
            for line in content.splitlines():
                if line.startswith('#HttpOnly_'): line=line[len('#HttpOnly_'):]
                if not line.strip() or line.startswith('#'): continue
                vals=line.split('\t')
                if len(vals)!=7: raise ValueError()
                domain,sub,pathpart,secure,expires,name,value=vals
                ck=http.cookiejar.Cookie(0,name,value,None,False,domain,True,domain.startswith('.'),pathpart,True,secure.upper()=='TRUE',int(expires) or None,False,None,None,{},False)
                jar.set_cookie(ck)
            return jar
        except (ValueError,TypeError):
            sys.stderr.write('could not parse specified cookie file "'+path+'"\n'); raise SystemExit(1)

    def permitted(self,target):
        if not self.opts.domain: return True
        try: host=url.urlsplit(target).hostname
        except ValueError: host=None
        if host is None:
            return True
        matches=False
        for domain in self.opts.domain:
            if domain.startswith('.'):
                if host.endswith(domain): matches=True
            elif host==domain: matches=True
        return not matches if self.opts.blacklist_domains else matches

    def get(self,target,referer=None):
        if not self.permitted(target):
            return Resource(b'','',target,successful=False,error='denied')
        try: p=url.urlsplit(target)
        except ValueError: return Resource(b'','',target,successful=False,error='invalid')
        scheme=p.scheme.lower()
        if scheme=='data':
            full=target.split('#',1)[0]
            header,sep,body=full[5:].partition(',')
            if not sep:
                return Resource(b'','text/plain',target,'text/plain')
            parts=header.split(';')
            mime=parts[0] or 'text/plain'
            params=[x for x in parts[1:] if x.lower()!='base64']
            mime+=''.join(';'+x for x in params)
            try:
                data=url.unquote_to_bytes(body)
                if any(x.lower()=='base64' for x in parts[1:]):
                    data=base64.b64decode(data,validate=True)
            except (ValueError,base64.binascii.Error): data=b''
            return Resource(data,mime,target,mime)
        if scheme=='file':
            path=url.unquote(p.path)
            try:
                if p.hostname not in (None,'','localhost'):
                    raise FileNotFoundError()
                with open(path,'rb') as stream: data=stream.read()
                self.log(target)
                mime=mime_for_path(path)
                return Resource(data,mime,target,mime)
            except OSError:
                self.log(target+' (file not found)')
                return Resource(b'','',target,successful=False,error='file')
        cache_key=target.split('#',1)[0]
        if cache_key in self.cache:
            self.log(target+' (from cache)')
            value=self.cache[cache_key]
            return Resource(value.data,value.mime,value.url,value.content_type,value.successful,value.error)
        if scheme not in ('http','https'):
            self.log(target+' (builder error for url ('+target+'))')
            return Resource(b'','',target,successful=False,error='unsupported')
        headers={'Accept':'*/*','User-Agent':self.opts.user_agent,'Accept-Encoding':'gzip, br, deflate'}
        if referer:
            try:
                rp=url.urlsplit(referer)
                if rp.scheme in ('http','https') and not (rp.scheme=='https' and scheme=='http'):
                    netloc=rp.netloc.split('@')[-1]
                    headers['Referer']=url.urlunsplit((rp.scheme,netloc,rp.path,rp.query,''))
            except ValueError: pass
        request_target=cache_key
        if p.username is not None:
            credential=url.unquote(p.username)+':'+url.unquote(p.password or '')
            headers['Authorization']='Basic '+base64.b64encode(credential.encode()).decode()
            request_target=url.urlunsplit((p.scheme,p.netloc.split('@')[-1],p.path,p.query,''))
        try:
            req=urllib.request.Request(request_target,headers=headers)
            try:
                response=self.opener.open(req,timeout=self.opts.timeout if self.opts.timeout else 0.000001)
            except urllib.error.HTTPError as ex:
                if not self.opts.ignore_errors:
                    msg=str(ex.code)+' '+str(ex.reason)
                    self.log(target+' ('+msg+')')
                    return Resource(b'','',target,successful=False,error='http')
                response=ex
            final=normalize_url(response.geturl()) or target
            if p.username is not None and response.geturl()==request_target: final=cache_key
            data=response.read()
            coding=response.headers.get('Content-Encoding','').lower()
            if coding=='gzip': data=gzip.decompress(data)
            elif coding=='deflate':
                try: data=zlib.decompress(data)
                except zlib.error: data=zlib.decompress(data,-zlib.MAX_WBITS)
            ctype=response.headers.get('Content-Type','')
            mime=ctype.split(';',1)[0].strip().lower() or 'application/octet-stream'
            response.close()
            if final!=cache_key:
                self.log(target+' -> '+final)
            else: self.log(target)
            result=Resource(data,mime,final,ctype)
            self.cache[cache_key]=result
            if final!=cache_key: self.cache[final]=result
            return result
        except Exception:
            self.log(target+' (error sending request for url ('+target+'))')
            return Resource(b'','',target,successful=False,error='network')
