    no_video: bool = False


def name_spec(opt):
    return '--'+opt[1]+(' <'+opt[2]+'>' if opt[2] else '')


def help_text(program):
    text=LOGO+'\n\nmonolith 2.11.0\n\nCLI tool and library for saving web pages as a single HTML file\n\nUsage: '+program+' [OPTIONS] <TARGET>\n\nArguments:\n  <TARGET>  URL or file path, use - for STDIN\n\nOptions:\n'
    for s,long,val,description in OPTIONS:
        label='  -'+s+', --'+long+(' <'+val+'>' if val else '')
        text += label.ljust(37)+description+'\n'
    return text


def parse_args(argv):
    program=os.path.basename(sys.argv[0])
    if program not in ('executable',):
        # The packaged entry point is named executable. This also makes running
        # the source directly useful for development.
        program='executable'
    opts=Options()
    seen=set()
    short={v[0]:v for v in OPTIONS}
    long={v[1]:v for v in OPTIONS}
    tail="\nFor more information, try '--help'.\n"
    def fail(message,usage=None,tips=''):
        sys.stderr.write('error: '+message+'\n'+tips)
        if usage is not None:
            sys.stderr.write('\nUsage: '+program+' '+usage+'\n')
        sys.stderr.write(tail)
        raise SystemExit(2)
    def unexpected(value,option=True):
        tips="\n  tip: to pass '"+value+"' as a value, use '-- "+value+"'\n" if option else ''
        fail("unexpected argument '"+value+"' found",'[OPTIONS] <TARGET>',tips)
    def set_option(opt,value=None):
        s,l,param,desc=opt
        if l=='help':
            sys.stdout.write(help_text(program)); raise SystemExit(0)
        if l=='version':
            sys.stdout.write('monolith 2.11.0\n'); raise SystemExit(0)
        if l in seen and l!='domain':
            fail("the argument '"+name_spec(opt)+"' cannot be used multiple times",'[OPTIONS] <TARGET>')
        seen.add(l)
        attr=l.replace('-','_')
        if l=='domain':
            opts.domain.append(value)
        elif l=='timeout':
            import re
            if not re.fullmatch(r'\+?[0-9]+',value):
                fail("invalid value '"+value+"' for '--timeout <60>': invalid digit found in string")
            if int(value)>(1<<64)-1:
                fail("invalid value '"+value+"' for '--timeout <60>': number too large to fit in target type")
            opts.timeout=int(value)
        else:
            setattr(opts,attr,value if param else True)
    idx=0
    positional=False
    target_set=False
    while idx<len(argv):
        arg=argv[idx]; idx+=1
        if not positional and arg=='--':
            positional=True; continue
        if not positional and arg.startswith('--'):
            body=arg[2:]
            key,eq,value=body.partition('=')
            if key not in long:
                unexpected('--'+key)
            opt=long[key]
            if opt[2]:
                if not eq:
                    if idx>=len(argv):
                        fail("a value is required for '"+name_spec(opt)+"' but none was supplied")
                    value=argv[idx]
                    if value.startswith('-') and value!='-':
                        unexpected(value if value.startswith('--') else value[:2])
                    idx+=1
                if value=='':
                    fail("a value is required for '"+name_spec(opt)+"' but none was supplied")
                set_option(opt,value)
            else:
                if eq:
                    fail("unexpected value '"+value+"' for '--"+key+"' found; no more were expected",'--'+key+' <TARGET>')
                set_option(opt)
        elif not positional and arg.startswith('-') and len(arg)>1:
            j=1
            while j<len(arg):
                ch=arg[j]; j+=1
                if ch not in short:
                    unexpected('-'+ch)
                opt=short[ch]
                if opt[2]:
                    if j<len(arg):
                        value=arg[j:]
                        if value.startswith('='): value=value[1:]
                        j=len(arg)
                    else:
                        if idx>=len(argv):
                            fail("a value is required for '"+name_spec(opt)+"' but none was supplied")
                        value=argv[idx]
                        if value.startswith('-') and value!='-': unexpected(value if value.startswith('--') else value[:2])
                        idx+=1
                    if not value: fail("a value is required for '"+name_spec(opt)+"' but none was supplied")
                    set_option(opt,value)
                else:
                    set_option(opt)
        else:
            if target_set: unexpected(arg,False)
            target_set=True
            opts.target=arg
    if not target_set:
        args=[]
        for item in OPTIONS:
            if item[1] in seen:
                if item[2]:
                    val=getattr(opts,item[1].replace('-','_'))
                    if isinstance(val,list): val=val[0] if val else ''
                    args.append(name_spec(item))
                else: args.append('--'+item[1])
        fail('the following required arguments were not provided:\n  <TARGET>',(' '.join(args)+' ' if args else '')+'<TARGET>')
    if opts.mhtml: opts.no_js=True
    return opts
