"""URLs, character encodings, and local/HTTP/data resource retrieval."""
from dataclasses import dataclass
import base64
import codecs
import gzip
import hashlib
import http.client
import http.cookiejar
import mimetypes
import os
import pathlib
import posixpath
import re
import ssl
import sys
import urllib.error
import urllib.parse as url
