def encoding(label):
    if not label: return None
    label=label.strip().lower()
    label=ENCODING_ALIASES.get(label,label)
    if label=='x-user-defined': return label
    try:
        name=codecs.lookup(label).name
        if name in ('utf-7','utf-32','utf-32-le','utf-32-be','unicode-escape','raw-unicode-escape','base64','hex','rot-13','unicode-internal'):
            return None
        return name
    except LookupError:
