"""CSS token rewriting with recursive URL and import embedding."""
import math
import re
import struct

ESCAPE=re.compile(r'\\(?:([0-9a-fA-F]{1,6})(?:\r\n|[\t\n\r\f ])?|\r\n|[\n\r\f]|(.))',re.S)

def css_unescape(text):
    def sub(m):
        if m.group(1):
            num=int(m.group(1),16)
            return chr(num) if 0<num<=0x10ffff and not 0xd800<=num<=0xdfff else '\ufffd'
        return m.group(2) or ''
    return ESCAPE.sub(sub,text)


def css_string(text):
    result='"'
    for c in text:
        n=ord(c)
        if c in ('"','\\'): result+='\\'+c
        elif n==0: result+='\ufffd'
        elif n<32 or n==127: result+='\\'+format(n,'x')+' '
        else: result+=c
    return result+'"'


def read_string(s,i):
    q=s[i]; j=i+1
    while j<len(s):
        if s[j]==q:
            return css_unescape(s[i+1:j]),j+1,True
        if s[j]=='\\':
            j+=2
            continue
        if s[j] in '\r\n\f':
            return css_unescape(s[i+1:j]),j,False
        j+=1
    return css_unescape(s[i+1:j]),j,True


def ident_end(s,i):
    j=i
    while j<len(s):
        c=s[j]
        if c.isalnum() or c in '_-' or ord(c)>=128:
            j+=1
        elif c=='\\' and j+1<len(s):
            m=ESCAPE.match(s,j)
            j=m.end() if m else j+2
        else: break
    return j


def css_ident(value):
    result=''
    for i,c in enumerate(value):
        if c=='\x00': result+='\ufffd'
        elif ord(c)<32 or ord(c)==127 or i==0 and c.isdigit() or i==1 and value[0]=='-' and c.isdigit():
            result+='\\'+format(ord(c),'x')+' '
        elif c.isalnum() or c in '_-' or ord(c)>=128:
            result+=c
        else: result+='\\'+c
    if result=='-': result='\\-'
    return result


def number_text(value):
    try:
        f=struct.unpack('f',struct.pack('f',float(value)))[0]
    except (ValueError,OverflowError): return value
    if f==0:
        if value.startswith('-'): return '+-0'
        if value.startswith('+'): return '+0'
        return '0'
    # Choose the shortest representation that round trips to the CSS f32.
    rendered=None
    for digits in range(1,10):
        test=format(f,'.'+str(digits)+'g')
        try:
            if struct.unpack('f',struct.pack('f',float(test)))[0]==f:
                rendered=test; break
        except OverflowError: pass
    rendered=rendered or str(f)
    if 'e' in rendered.lower():
        try:
            if 1e-6<=abs(f)<1e21:
                rendered=format(float(rendered),'f').rstrip('0').rstrip('.')
                if rendered=='-0': rendered='0'
        except ValueError: pass
    if value.startswith('+') and not rendered.startswith('-'): rendered='+'+rendered
    return rendered


